INSERT INTO feature VALUES('package-lock','modules','A package''s lock of the coordinates its sources import','packages','implemented','ordinary',NULL,'A source imports a package by its coordinate, `import "path:../hello" as hello ;`, a path from the package''s root to a directory rooting another package, and binds that package''s root module under the alias, `hello.welcome`; a source in no package reads the coordinate from its own directory, with no lock. A module path headed by the alias, `import hello.text.greet (greeting) ;`, names the module `text/greet.gandr` under the dependency''s sources, through the coordinate''s own lock entry. `import "gh:acme-org/rope" as rope ;` names the repository on GitHub whose top directory roots the package, at the revision the lock records: `gandr lock` asks the remote''s `HEAD` for a coordinate its lock does not record and keeps one it does, and the driver fetches the revision alone with `git` into `gandr/checkouts` under the XDG cache home, once per revision; `gandr check` fetches only a revision the lock records, and refuses a coordinate it records none of, naming `gandr lock`. `gandr check` collects every coordinate the package''s sources import, each once, and resolves each to the package it roots, a dependency''s own dependencies first and its own lock checked against them, commits its identity, its address and its signature key, the digest of the paths its root exports, to the store under the XDG data home, and writes its lock when none stands, `package.gandr.lock` beside its package source, or, for a package below a workspace, its own table of the `workspace.gandr.lock` every package below the workspace shares, keyed by its root''s path from the workspace''s: one line per coordinate with the pointer the identity commits to, `<digest>:<offset>`, after the revision for a `gh:` one. The lock is the same bytes resolved from any directory into any store, a second run and an inert edit to a dependency leave it, and any other difference, or a hand edit, is refused `LockDrift.<coordinate>` and left as it stands until `gandr lock` writes it again; a pointer the store cannot read back leaves the dependent unaddressed, naming the coordinate. A coordinate the lock does not record refuses each use through its alias `UnlockedDependency`, so the coordinates are collected before the lock is written, and a module path naming no module of the package refuses each use the same way; two packages depending on each other are refused `DependencyCycle` by their roots.','storage-store surface-dispatcher surface-driver surface-lowering','corpus/model/projects/tools/package.gandr corpus/model/projects/workspace.gandr.lock corpus/ledger/diagnostics/UnlockedDependency.gandr crates/surface-dispatcher/tests/package.rs::a_lock_is_written_once_and_reads_alike_from_anywhere_3072 crates/surface-dispatcher/tests/package.rs::a_dependency_s_content_edit_drifts_the_lock_until_relocked_3072 crates/surface-dispatcher/tests/package.rs::a_dependency_cycle_is_refused_by_its_paths_3072 crates/surface-dispatcher/tests/package.rs::a_pointer_the_store_cannot_answer_leaves_the_dependent_unaddressed_3157 crates/surface-dispatcher/tests/package.rs::a_gh_coordinate_is_fetched_at_the_revision_its_lock_records_4714 crates/surface-dispatcher/tests/package.rs::a_module_path_through_a_coordinate_s_alias_reads_the_dependency_s_module_4715 crates/surface-driver/tests/cli.rs::check_writes_a_lock_and_refuses_its_drift_3072 crates/surface-driver/tests/cli.rs::a_package_s_lock_points_into_the_store_the_run_opens_3157 crates/surface-driver/tests/cli.rs::a_gh_coordinate_is_fetched_locked_and_read_again_4714 crates/surface-lowering/tests/namespace.rs::a_name_read_through_an_unlocked_alias_is_refused_at_it_3072','corpus/model/projects/tools/package.gandr',NULL);
